def jax_batchnorm(x, gamma, beta):
    mean = jnp.mean(x, axis=0, keepdims=True)
    var = jnp.var(x, axis=0, keepdims=True)
    return gamma * (x - mean) / jnp.sqrt(var + 1e-5) + beta

def jax_huber(pred, target, delta=1.0):
    diff = pred - target
    return jnp.mean(jnp.where(jnp.abs(diff) <= delta, 0.5*diff**2, delta*(jnp.abs(diff)-0.5*delta)))

def jax_layernorm(x):
    mean = jnp.mean(x, axis=-1, keepdims=True)
    var = jnp.var(x, axis=-1, keepdims=True)
    return (x - mean) / jnp.sqrt(var + 1e-5)

def jax_revcomp(seq):
    comp = jnp.array([3,2,1,0])
    return comp[seq[::-1]]

def jax_attn(q, k, v):
    scores = q @ k.swapaxes(-2,-1) / jnp.sqrt(q.shape[-1])
    return jax.nn.softmax(scores, axis=-1) @ v
